```ts
import { test, expect } from '@playwright/test';

test('search finds a pharmacist by last name', async ({ page }) => {
  await page.goto('/pharmacists');
  const search = page.getByPlaceholder('Search pharmacists');
  await search.fill('Rivera');
  await search.press('Enter');
  await expect(page.getByRole('row').filter({ hasText: 'Rivera' })).toBeVisible();
});
```
